#!/bin/bash
set -e

echo "=========================================================="
echo "  Configurazione Maestro Studio su PORTA 5000"
echo "=========================================================="

APP_DIR="/var/www/maestro-studio"
mkdir -p "/app/applet"
cd "/app/applet"

echo "=== [1/5] Estrazione codice aggiornato ==="
sed '1,/^###TAR_PAYLOAD_START###$/d' "sh" | base64 -d | tar -xzf -

echo "=== [2/5] Verifica dipendenze ==="
if [ ! -d "node_modules" ]; then
  npm install
fi

echo "=== [3/5] Aggiornamento Nginx su porta 5000 ==="
# Aggiorna qualsiasi blocco /Song o /song in /etc/nginx verso 127.0.0.1:5000
for conf in /etc/nginx/sites-available/* /etc/nginx/sites-enabled/* /etc/nginx/conf.d/*; do
  if [ -f "" ]; then
    if grep -q -i 'location.*Song' ""; then
      echo "Modifica file Nginx:  -> 127.0.0.1:5000"
      sed -i 's|http://127.0.0.1:3000|http://127.0.0.1:5000|g' ""
      sed -i 's|http://localhost:3000|http://127.0.0.1:5000|g' ""
    fi
  fi
done

# Verifica se esiste la config specifica freeserv
if [ -f "/etc/nginx/sites-available/freeserv" ]; then
  sed -i 's|http://127.0.0.1:3000|http://127.0.0.1:5000|g' /etc/nginx/sites-available/freeserv
  sed -i 's|http://localhost:3000|http://127.0.0.1:5000|g' /etc/nginx/sites-available/freeserv
fi

# Ricarica Nginx in modo sicuro
nginx -t && (systemctl reload nginx || systemctl restart nginx)

echo "=== [4/5] Riavvio PM2 su PORTA 5000 ==="
# Pulizia vecchi processi
pm2 delete maestro 2>/dev/null || true
pm2 delete maestro-studio 2>/dev/null || true

# Avvio esplicito con PORT=5000
PORT=5000 pm2 start server.ts --name "maestro-studio" --interpreter tsx --update-env
pm2 save

echo "=== [5/5] Test del server su porta 5000 ==="
sleep 2
CODE="000"
echo "Test HTTP /Song: "

echo "=========================================================="
echo " SUCCESSO! L'app e' attiva sulla PORTA 5000"
echo " La porta 3000 e' ora libera per l'altro sito!"
echo " Raggiungibile su: http://freeserv.it/Song#piano"
echo "=========================================================="
exit 0
###TAR_PAYLOAD_START###

